import type { MetadataRoute } from "next";
import { db } from "@/lib/db";
import { TOOL_SLUGS } from "@/lib/tools/catalog";
import { LANDING_SLUGS, REGION_LANDING_SLUGS } from "@/lib/marketing/locationLandings";
import { GAME_LOCATION_SLUGS, GENERAL_LOCATION_SLUGS } from "@/lib/marketing/gameLocationLandings";
import { countIndexableMods, listIndexableModSlugsChunk, modChunkCountFor } from "@/lib/sitemap-mods";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const dynamic = "force-dynamic";

/**
 * Sitemap INDEX split — see lib/sitemap-mods.ts's header for the full
 * rationale (Google's real 50,000-URL-per-file cap, breached the moment the
 * ~45,761 NxLabs mod URLs shared one file with the ~1,460 other marketing
 * routes). `id: 0` is every non-mod route this file used to return in one
 * flat array — unchanged content, just no longer sharing a file with mod
 * URLs. `id: 1..N` are mod URL chunks of `MOD_SITEMAP_CHUNK_SIZE` each,
 * computed fresh every call so the id list — and therefore the real
 * `<sitemapindex>` at /sitemap.xml (app/sitemap.xml/route.ts) — always
 * matches the live catalogue size, growing automatically as more mods are
 * imported rather than needing a manual bump.
 *
 * Resulting URLs: /sitemap/0.xml (static), /sitemap/1.xml..N.xml (mods).
 * Next.js does NOT build a combined /sitemap.xml index automatically once
 * generateSitemaps() is present (confirmed against the installed next@15.5.21
 * — see app/sitemap.xml/route.ts's header) — that index is hand-written
 * there instead, listing exactly these same ids.
 */
export async function generateSitemaps(): Promise<Array<{ id: number }>> {
  const modCount = await countIndexableMods();
  const modChunks = modChunkCountFor(modCount);
  return Array.from({ length: modChunks + 1 }, (_, i) => ({ id: i }));
}

/**
 * `<lastmod>` for routes whose content isn't row-backed (the static marketing
 * pages, the hub pages, the generated location landings).
 *
 * This is deliberately NOT `new Date()`. The route is force-dynamic, so a
 * request-time timestamp made every one of the ~47,000 URLs claim it had
 * changed the instant Google fetched the file — a fresh value on every single
 * crawl, for pages that had not changed at all. Google's own guidance is that
 * it ignores (and distrusts) `lastmod` when it can't be trusted, so the signal
 * was worse than useless: it burned crawl budget re-fetching unchanged pages
 * and devalued the dates on the pages that DO carry a real one.
 *
 * These pages change when the code changes, so the deploy's own build stamp is
 * the honest answer. BUILD_TIME is written at build time by next.config.ts;
 * the fallback keeps the value stable within a process rather than per-request.
 */
const BUILD_STAMP = new Date(process.env.BUILD_TIME ?? process.env.NEXT_PUBLIC_BUILD_TIME ?? Date.now());

export default async function sitemap({ id }: { id?: string | number } = {}): Promise<MetadataRoute.Sitemap> {
  const chunkId = Number(id ?? 0);
  const now = BUILD_STAMP;

  // ── Mod URL chunks (id 1..N) ─────────────────────────────────────────
  if (chunkId > 0) {
    const modSlugs = await listIndexableModSlugsChunk(chunkId - 1);
    return modSlugs.map((m) => ({
      url: `${APP_URL}/mods/${m.family}/${m.slug}`,
      // The mod's own last-changed date, not the crawl time.
      lastModified: m.lastModified,
      changeFrequency: "weekly" as const,
      priority: 0.5,
    }));
  }

  // ── Everything else (id 0) — unchanged from the original single-file
  // sitemap, just no longer sharing a file with the mod URLs above. ─────

  const staticRoutes: Array<{ path: string; priority: number; freq: MetadataRoute.Sitemap[number]["changeFrequency"] }> = [
    // "/" not "" — an empty path emitted <loc>https://nxeon.cloud</loc> with no
    // path component at all. Google normalises that to the trailing-slash form
    // anyway, but several third-party validators flag it and there is no reason
    // for the canonical homepage entry to be the one line that needs excusing.
    { path: "/", priority: 1.0, freq: "weekly" },
    { path: "/features", priority: 0.8, freq: "monthly" },
    { path: "/vibe-coding", priority: 0.8, freq: "monthly" },
    { path: "/matrix", priority: 0.9, freq: "monthly" },
    { path: "/pricing", priority: 0.9, freq: "weekly" },
    { path: "/vps", priority: 0.8, freq: "monthly" },
    { path: "/web-hosting", priority: 0.8, freq: "monthly" },
    { path: "/domains", priority: 0.8, freq: "monthly" },
    // Core product / landing pages that shipped after the original list was
    // written — all indexable (unlike the noindex /v2–/v8 homepage previews).
    { path: "/business-email", priority: 0.8, freq: "monthly" },
    { path: "/game-servers", priority: 0.8, freq: "monthly" },
    { path: "/game-servers/mods", priority: 0.7, freq: "monthly" },
    { path: "/free-minecraft", priority: 0.8, freq: "monthly" },
    { path: "/servers", priority: 0.7, freq: "daily" },
    { path: "/block-storage", priority: 0.8, freq: "monthly" },
    { path: "/nxcloud", priority: 0.7, freq: "monthly" },
    { path: "/docs", priority: 0.6, freq: "weekly" },
    { path: "/migrate", priority: 0.7, freq: "monthly" },
    { path: "/security", priority: 0.6, freq: "monthly" },
    { path: "/developers", priority: 0.6, freq: "monthly" },
    { path: "/affiliate", priority: 0.5, freq: "monthly" },
    { path: "/compare", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-digitalocean", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-hostinger", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-a2hosting", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-bluehost", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-cloudways", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-godaddy", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-hostgator", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-ionos", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-kamatera", priority: 0.7, freq: "monthly" },
    { path: "/vps-vs-namecheap", priority: 0.7, freq: "monthly" },
    // "Move from X to Nxeon" migration-intent pages — paired 1:1 with the
    // vps-vs-X comparison pages above (see app/(marketing)/migrate-from-*).
    { path: "/migrate-from-a2hosting", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-bluehost", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-cloudways", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-digitalocean", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-godaddy", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-hostgator", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-hostinger", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-ionos", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-kamatera", priority: 0.7, freq: "monthly" },
    { path: "/migrate-from-namecheap", priority: 0.7, freq: "monthly" },
    // Competitor "alternative" comparison pages.
    { path: "/hetzner-alternative", priority: 0.7, freq: "monthly" },
    { path: "/contabo-alternative", priority: 0.7, freq: "monthly" },
    { path: "/vultr-alternative", priority: 0.7, freq: "monthly" },
    { path: "/linode-alternative", priority: 0.7, freq: "monthly" },
    { path: "/ovh-alternative", priority: 0.7, freq: "monthly" },
    { path: "/aws-lightsail-alternative", priority: 0.7, freq: "monthly" },
    // High-intent "host X on a VPS" use-case pages.
    { path: "/wordpress-vps-hosting", priority: 0.8, freq: "monthly" },
    { path: "/docker-hosting", priority: 0.8, freq: "monthly" },
    { path: "/n8n-hosting", priority: 0.8, freq: "monthly" },
    { path: "/nodejs-hosting", priority: 0.8, freq: "monthly" },
    { path: "/nextcloud-hosting", priority: 0.8, freq: "monthly" },
    { path: "/vpn-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/discord-bot-hosting", priority: 0.8, freq: "monthly" },
    { path: "/minecraft-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/rust-server-hosting", priority: 0.7, freq: "monthly" },
    // Buyer-intent game-server + gaming-VPS landing pages (high-impression queries).
    { path: "/gaming-vps", priority: 0.8, freq: "monthly" },
    { path: "/palworld-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/valheim-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/ark-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/7-days-to-die-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/project-zomboid-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/v-rising-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/enshrouded-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/satisfactory-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/terraria-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/cs2-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/garrys-mod-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/fivem-server-hosting", priority: 0.8, freq: "monthly" },
    { path: "/factorio-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/conan-exiles-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/unturned-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/the-forest-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/sons-of-the-forest-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/minecraft-bedrock-server-hosting", priority: 0.7, freq: "monthly" },
    // Wave 3 dedicated game plans (2026-08-31) — RuneScape: Dragonwilds, Sunkenland,
    // Abiotic Factor, Core Keeper, Icarus. Same GamePlan+OsTemplate pattern as the
    // titles above, using the "Combined" flagship landing design.
    { path: "/dragonwilds-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/sunkenland-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/abiotic-factor-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/core-keeper-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/icarus-server-hosting", priority: 0.7, freq: "monthly" },
    // Wave 4 dedicated game plans (2026-08-31) — ARK: Survival Ascended, Soulmask,
    // Don't Starve Together, Vintage Story, Necesse, Team Fortress 2, Left 4 Dead 2.
    { path: "/ark-survival-ascended-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/soulmask-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/dont-starve-together-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/vintage-story-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/necesse-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/tf2-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/left-4-dead-2-server-hosting", priority: 0.7, freq: "monthly" },
    // Wave 8/9 dedicated game plans (2026-08-31) — Nightingale, Squad, Space
    // Engineers, Killing Floor 2, Barotrauma, Insurgency: Sandstorm, Mordhau,
    // The Isle, Eco, Empyrion. These had real seeded GamePlan rows and
    // key-art but no landing page at all until the 2026-09-14 SEO gap-fill
    // audit found and closed the gap. Stationeers is deliberately EXCLUDED —
    // docs/DOCUMENTATION.md's "Stationeers cannot be sold today" finding
    // confirmed live that didstopia/stationeers-server never binds a port or
    // creates a world. It still has an active GamePlan row and shows on
    // /game-servers today, but a dedicated SEO page would actively drive paid
    // signups to a product that does not start — flagged for follow-up
    // rather than shipped around.
    { path: "/nightingale-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/squad-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/space-engineers-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/killing-floor-2-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/barotrauma-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/insurgency-sandstorm-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/mordhau-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/the-isle-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/eco-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/empyrion-server-hosting", priority: 0.7, freq: "monthly" },
    // Specialty/community server hosting — deliberately NOT part of the
    // flagship game grid above (see app/(marketing)/game-servers/page.tsx's
    // "Specialty & community servers" section + prisma/seed-plutonium.ts for
    // the full framing). Lower priority than the flagship titles above since
    // it's a niche product, not a mainstream one.
    { path: "/plutonium-t4-hosting", priority: 0.5, freq: "monthly" },
    { path: "/plutonium-t5-hosting", priority: 0.5, freq: "monthly" },
    { path: "/plutonium-t6-hosting", priority: 0.5, freq: "monthly" },
    { path: "/plutonium-iw5-hosting", priority: 0.5, freq: "monthly" },
    // Budget + location intent pages.
    { path: "/cheap-vps-hosting", priority: 0.8, freq: "monthly" },
    { path: "/affordable-vps-hosting", priority: 0.7, freq: "monthly" },
    { path: "/best-value-vps", priority: 0.7, freq: "monthly" },
    { path: "/free-vps", priority: 0.7, freq: "monthly" },
    { path: "/singapore-vps-hosting", priority: 0.7, freq: "monthly" },
    // Remaining Singapore combos migrated onto the LocationLanding template
    // (components/marketing/locationtemplate) — reserved out of LANDING_SLUGS
    // in lib/marketing/locationLandings.ts, so they need a manual entry here
    // the same way singapore-vps-hosting above does.
    { path: "/singapore-game-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/singapore-web-hosting", priority: 0.7, freq: "monthly" },
    { path: "/singapore-dedicated-server-hosting", priority: 0.7, freq: "monthly" },
    { path: "/singapore-forex-vps-hosting", priority: 0.7, freq: "monthly" },
    { path: "/singapore-reseller-hosting", priority: 0.7, freq: "monthly" },
    { path: "/about", priority: 0.5, freq: "monthly" },
    { path: "/contact", priority: 0.5, freq: "monthly" },
    { path: "/blog", priority: 0.7, freq: "weekly" },
    { path: "/tools", priority: 0.7, freq: "weekly" },
    ...TOOL_SLUGS.map((slug) => ({
      path: `/tools/${slug}`,
      priority: 0.6,
      freq: "monthly" as const,
    })),
    { path: "/status", priority: 0.4, freq: "daily" },
    { path: "/legal/terms", priority: 0.3, freq: "yearly" },
    { path: "/legal/privacy", priority: 0.3, freq: "yearly" },
    { path: "/legal/aup", priority: 0.3, freq: "yearly" },
    { path: "/legal/sla", priority: 0.3, freq: "yearly" },
  ];

  const entries: MetadataRoute.Sitemap = staticRoutes.map((r) => ({
    url: `${APP_URL}${r.path}`,
    lastModified: now,
    changeFrequency: r.freq,
    priority: r.priority,
  }));

  // Programmatic "(location) (service)" landing pages (lib/marketing/locationLandings.ts).
  for (const slug of LANDING_SLUGS) {
    entries.push({
      url: `${APP_URL}/${slug}`,
      lastModified: now,
      changeFrequency: "monthly",
      priority: 0.7,
    });
  }

  // Region-tier umbrella landing pages above the city matrix (same file) —
  // e.g. /usa-vps-hosting, /europe-game-server-hosting. Slightly higher
  // priority than a single city page since they target more generic,
  // higher-volume queries ("american vps hosting").
  for (const slug of REGION_LANDING_SLUGS) {
    entries.push({
      url: `${APP_URL}/${slug}`,
      lastModified: now,
      changeFrequency: "monthly",
      priority: 0.75,
    });
  }

  // Game family × location landing pages (lib/marketing/gameLocationLandings.ts)
  // — e.g. /singapore-minecraft-server-hosting, /germany-valheim-server-hosting.
  // Slightly lower priority than the flagship single-game pages (0.7-0.8 above)
  // since these are the longer-tail cross-product of the two axes.
  for (const slug of GAME_LOCATION_SLUGS) {
    entries.push({
      url: `${APP_URL}/${slug}`,
      lastModified: now,
      changeFrequency: "monthly",
      priority: 0.6,
    });
  }

  // General "[Location] VPS/Game Server Hosting" pages for the locations in
  // that same file's GAME_LOCATIONS table that don't already have one via
  // the tables above (Singapore/Germany/Europe are skipped there — already
  // covered by RESERVED_SLUGS / COMBOS / REGION_COMBOS respectively).
  for (const slug of GENERAL_LOCATION_SLUGS) {
    entries.push({
      url: `${APP_URL}/${slug}`,
      lastModified: now,
      changeFrequency: "monthly",
      priority: 0.7,
    });
  }

  // Published blog posts (model may not be migrated yet — access defensively).
  try {
    const blogModel = (db as unknown as { blogPost?: { findMany: (a: unknown) => Promise<Array<{ slug: string; updatedAt: Date }>> } }).blogPost;
    const posts = blogModel
      ? await blogModel.findMany({
          where: { published: true },
          select: { slug: true, updatedAt: true },
          orderBy: { publishedAt: "desc" },
        })
      : [];
    for (const p of posts) {
      entries.push({
        url: `${APP_URL}/blog/${p.slug}`,
        lastModified: p.updatedAt,
        changeFrequency: "monthly",
        priority: 0.6,
      });
    }
  } catch {
    // blogPost model not migrated yet — skip.
  }

  // Public free-Minecraft server pages (/servers/[subdomain]) — same opt-in
  // gate as the page itself (isPublic + READY), so the sitemap never points a
  // crawler at a server whose owner hasn't chosen to list it. Uncapped here
  // (unlike the /servers directory page, which caps its display at 48) since
  // a sitemap listing more entries than a page shows is normal and desirable
  // for indexing — every public server should be crawlable even if it's
  // beyond the directory's newest-48 display cap.
  try {
    const freeServers = await db.freeMinecraftServer.findMany({
      where: { isPublic: true, status: "READY" },
      select: { subdomain: true, createdAt: true },
    });
    for (const s of freeServers) {
      entries.push({
        url: `${APP_URL}/servers/${s.subdomain}`,
        lastModified: s.createdAt,
        changeFrequency: "weekly",
        priority: 0.5,
      });
    }
  } catch {
    // Defensive, matching the blogPost handling above — should never actually
    // throw since FreeMinecraftServer ships in this same migration.
  }

  // NxLabs — the public mod/plugin catalog's own browse index page (just the
  // one /mods URL). The 45,761+ individual mod detail URLs
  // (lib/mods-catalog.ts's active+upstreamOk filter) are NOT pushed here —
  // they're served through their own chunked sitemap ids above/at
  // lib/sitemap-mods.ts, kept off this file entirely so this sitemap can
  // never approach Google's 50,000-URL cap again regardless of how large the
  // catalogue grows.
  entries.push({ url: `${APP_URL}/mods`, lastModified: now, changeFrequency: "weekly", priority: 0.7 });

  return entries;
}

