import os, re, json, sys
from html.parser import HTMLParser

PAGES = sys.argv[1] if len(sys.argv) > 1 else "pages"

class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.title = None; self._in_title = False; self._tbuf = []
        self.metas = {}; self.links = []; self.canon = []
        self.h = []; self._hstack = None; self._hbuf = []
        self.imgs = []; self.jsonld = []; self._in_ld = False; self._ldbuf = []
        self.hrefs = []
        self.in_head = False
        self.body_started = False
    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == "title" and self.title is None:
            self._in_title = True; self._tbuf = []
        elif tag == "meta":
            k = a.get("name") or a.get("property")
            if k:
                self.metas.setdefault(k.lower(), []).append(a.get("content", ""))
        elif tag == "link" and a.get("rel") == "canonical":
            self.canon.append(a.get("href"))
        elif tag in ("h1","h2","h3","h4"):
            self._hstack = tag; self._hbuf = []
        elif tag == "img":
            self.imgs.append((a.get("src") or a.get("srcset") or "")[:120] if True else "")
            self.imgs[-1] = (self.imgs[-1], a.get("alt"))
        elif tag == "script" and a.get("type") == "application/ld+json":
            self._in_ld = True; self._ldbuf = []
        elif tag == "a":
            h = a.get("href")
            if h: self.hrefs.append(h)
    def handle_endtag(self, tag):
        if tag == "title" and self._in_title:
            self._in_title = False; self.title = "".join(self._tbuf).strip()
        elif tag == self._hstack:
            self.h.append((tag, re.sub(r"\s+"," ","".join(self._hbuf)).strip()[:140])); self._hstack = None
        elif tag == "script" and self._in_ld:
            self._in_ld = False; self.jsonld.append("".join(self._ldbuf))
    def handle_data(self, d):
        if self._in_title: self._tbuf.append(d)
        if self._hstack: self._hbuf.append(d)
        if self._in_ld: self._ldbuf.append(d)

def ld_types(raw):
    out = []
    try:
        j = json.loads(raw)
    except Exception:
        return ["<invalid-json>"]
    def walk(x):
        if isinstance(x, dict):
            t = x.get("@type")
            if t: out.append(t if isinstance(t,str) else ",".join(t))
            for v in x.values(): walk(v)
        elif isinstance(x, list):
            for v in x: walk(v)
    walk(j)
    return out

res = {}
for fn in sorted(os.listdir(PAGES)):
    if not fn.endswith(".html"): continue
    path = os.path.join(PAGES, fn)
    html = open(path, encoding="utf-8", errors="replace").read()
    p = P()
    try:
        p.feed(html)
    except Exception as e:
        pass
    types = []
    for raw in p.jsonld: types += ld_types(raw)
    res[fn[:-5]] = {
        "title": p.title,
        "desc": (p.metas.get("description") or [None])[0],
        "robots": p.metas.get("robots"),
        "canon": p.canon,
        "og_title": (p.metas.get("og:title") or [None])[0],
        "og_image": (p.metas.get("og:image") or [None])[0],
        "og_url": (p.metas.get("og:url") or [None])[0],
        "tw_card": (p.metas.get("twitter:card") or [None])[0],
        "h": p.h,
        "imgs": p.imgs,
        "ld": types,
        "hrefs": p.hrefs,
        "size": len(html),
    }
json.dump(res, open(PAGES.rstrip("/") + "_seo.json", "w"))
print(len(res))

