type Counters = { seen: number; qualified: number; upserted: number; created: number; updated: number; skipped: number; failed: number };
function emptyCounters(): Counters {
  let page = 0;
  let total: number | undefined;
  const qualifiedBatch: PublishedFile[] = [];

  for (;;) {
    if (maxPages !== undefined && page >= maxPages) break;
    if (counters.qualified >= maxPerFamily) break;

    const url =
      `${API}/IPublishedFileService/QueryFiles/v1/` +
      `?key=${STEAM_KEY}&appid=${appid}&numperpage=${PAGE_SIZE}&cursor=${encodeURIComponent(cursor)}` +
      `&query_type=${RANKED_BY_TOTAL_UNIQUE_SUBSCRIPTIONS}&return_short_description=true&format=json`;
    const res = await apiFetch(limiter, url);
    page++;
    if (!res.ok) {
      console.error(`  [${family}] HTTP ${res.status} at page ${page} — stopping this family early`);
      break;
    }
    const body = (await res.json()) as QueryFilesResponse & { response: { next_cursor?: string } };
    const items = body.response.publishedfiledetails ?? [];
    total = body.response.total ?? total;
    counters.seen += items.length;
    if (items.length === 0) break;

    let sawBelowFloor = false;
    for (const item of items) {
      if (item.result !== 1 || item.banned || (item.visibility ?? 0) !== 0) continue;
      const subs = item.subscriptions ?? 0;
      if (subs < minSubscriptions) {
        sawBelowFloor = true;
        break; // sorted descending by subscriptions — nothing after this qualifies either
      }
      if (!item.title || !item.publishedfileid) continue;
      qualifiedBatch.push(item);
      counters.qualified++;
      if (counters.qualified >= maxPerFamily) break;
    }

    const nextCursor = (body.response as { next_cursor?: string }).next_cursor;
    console.log(
      `  [${family}] page=${page} fetched=${items.length} qualified_running=${counters.qualified} total=${total ?? "?"}`
    );
    if (sawBelowFloor || !nextCursor || nextCursor === cursor) break;
    cursor = nextCursor;
  }

  if (qualifiedBatch.length === 0) {
    console.log(`  [${family}] nothing qualified (floor=${minSubscriptions} subscribers)`);
    return counters;
  }

  if (!apply) {
    counters.upserted = qualifiedBatch.length;
    return counters;
  }

  const authors = await fetchAuthors(limiter, qualifiedBatch.map((i) => i.creator ?? ""));
  const CONCURRENCY = 8;
  for (let i = 0; i < qualifiedBatch.length; i += CONCURRENCY) {
    const slice = qualifiedBatch.slice(i, i + CONCURRENCY);
    await Promise.all(
      slice.map(async (item) => {
        const publishedFileId = item.publishedfileid;
        const slug = `${kebab(item.title!)}-${publishedFileId.slice(-6)}`;
        const author = item.creator ? authors.get(item.creator) : undefined;
        const data = {
          name: item.title!,
          category: "Workshop",
          description: item.short_description || null,
          iconUrl: item.preview_url || null,
          url: `https://steamcommunity.com/sharedfiles/filedetails/?id=${publishedFileId}`,
          downloads: item.subscriptions ?? null,
          license: null,
          serverSide: null,
          galleryUrls: [] as string[],
          authorName: author?.personaname ?? null,
          authorAvatarUrl: author?.avatarfull ?? null,
          source: "steam_workshop",
          sourceId: publishedFileId,
          active: true,
          verifiedAt: new Date(),
          upstreamOk: true,
          upstreamNote: null,
        };
        try {
          const existing = await db.gameMod.findUnique({
            where: { gameFamily_slug: { gameFamily: family, slug } },
            select: { id: true },
          });
          // select: { id: true } — a concurrent agent worktree sharing this
          // tree's node_modules regenerated the Prisma client against a schema
          // ahead of this database (a real `longDescription` column drift,
          // unrelated to this script); limiting the returned shape avoids
          // asking Postgres for a column this database doesn't have yet
          // rather than papering over it by touching the shared client.
          await db.gameMod.upsert({
            where: { gameFamily_slug: { gameFamily: family, slug } },
            update: data,
            create: { gameFamily: family, slug, ...data },
            select: { id: true },
          });
          counters.upserted++;
          if (existing) counters.updated++;
          else counters.created++;
        } catch (e) {
          counters.failed++;
          console.error(`  [db] ${family}/${slug} failed:`, e instanceof Error ? e.message : e);
        }
      })
    );
  }
  return counters;
}

