/** True if an IPv6 address sits in a range we refuse to connect to. */
function isBlockedIpv6(ip: string): boolean {
  let addr = ip.toLowerCase();
  // Strip a zone id (fe80::1%eth0) before classifying.
  const pct = addr.indexOf("%");
  if (pct !== -1) addr = addr.slice(0, pct);

  // IPv4-mapped / -compatible (::ffff:1.2.3.4) — classify by the embedded IPv4.
  const mapped = addr.match(/:((?:\d{1,3}\.){3}\d{1,3})$/);
  if (mapped) return isBlockedIpv4(mapped[1]);

  if (addr === "::1" || addr === "::") return true; // loopback / unspecified
  const head = addr.split(":")[0] ?? "";
  const h = parseInt(head || "0", 16);
  if (Number.isNaN(h)) return true; // unparseable — refuse
  // fc00::/7 unique-local (fc.. or fd..)
  if ((h & 0xfe00) === 0xfc00) return true;
  // fe80::/10 link-local
  if ((h & 0xffc0) === 0xfe80) return true;
  return false;
}

